#!/bin/bash

# Remove only the files generated by this experiment.
rm -f trace_fifo_a trace_fifo_b strace_a.txt strace_b.txt

# Summarize filesystem-related system calls for each command.
strace -o strace_a.txt -c -e trace=%file \
    mknod trace_fifo_a p
status_a=$?

strace -o strace_b.txt -c -e trace=%file \
    mkfifo trace_fifo_b
status_b=$?

echo "mknod exit status: $status_a"
echo "mkfifo exit status: $status_b"

echo
echo "mknod system-call summary:"
cat strace_a.txt

echo
echo "mkfifo system-call summary:"
cat strace_b.txt

# Keep the trace summaries for inspection; remove only the FIFOs.
rm -f trace_fifo_a trace_fifo_b

